contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint value) public payable {
        uint cBalBefore = address(c).balance;
        require(value <= cBalBefore);

        bool reverted;
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint cBalAfter = address(c).balance;

        assert(
            (reverted && cBalAfter == cBalBefore) ||
            (!reverted && cBalAfter == cBalBefore - value)
        );
    }
}

